contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function testTransferReturn(uint256 amount) public {
        require(amount <= c.balanceOf(address(this)));
        bool ok = c.transfer(address(this), 0); if (__ESBMC_reverted()) return;
        require(amount >= 0);
        ok = c.transfer(address(1), amount); if (__ESBMC_reverted()) return;
        assert(ok == true);
    }

    receive() external payable {}
    fallback() external payable {}
}

