        c = new ERCDDAToken(0, "", "");
    }

    function _testTransferReturn(uint256 amount) internal {
        vm.assume(amount <= c.balanceOf(address(this)));
        bool ok;
        try c.transfer(address(this), 0) returns (bool __r) { ok = __r; } catch { return; }
        vm.assume(amount >= 0);
        try c.transfer(address(1), amount) returns (bool __r) { ok = __r; } catch { return; }
        assertTrue(ok == true);
    }

    function testFuzz_testTransferReturn(uint256 amount) public {
        _testTransferReturn(amount);
    }

    receive() external payable {}

    fallback() external payable {}
